  ?z a brick:zone .
  ?z rdfs:label ?label .
  FILTER(?label IN ("Basement", "DataCenter_top_ZN_6"))
  OPTIONAL { ?z ref:hasExternalReference ?ref . ?z ref:hasTimeseriesId ?ts }
}

SELECT ?z ?label ?cls WHERE {
  ?z a ?cls .
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "Basement") || CONTAINS(?label, "DataCenter_top"))
}

SELECT ?sensor ?ts WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor brick:hasLocation [ rdfs:label ?label ; a brick:HVAC_Zone ] .
  FILTER(?label IN ("Basement", "DataCenter_top_ZN_6"))
  ?sensor ref:hasTimeseriesId ?ts
}

SELECT ?sensor ?loc ?label ?ts WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
